INSERT OR REPLACE INTO post_translations (post_id, locale, title, summary, body_md, body_html, reading_minutes, updated_at) VALUES ('22222222-2222-4222-8222-222222222222', 'uz', 'OY Lab kuzgi oʼqishlar dasturi', 'Oktabr va noyabr oylarida har chorshanba kuni ochiq maʼruzalar: tilshunoslik, ilmiy hisoblash va tizimlar.', 'Kuz boshlandi, biz esa oʼqishlarni qayta ochamiz. Har chorshanba soat 18:00 da laboratoriya zalida ochiq maʼruza boʼladi. Kirish bepul, roʼyxatdan oʼtish shart emas.

## Dastur

- **8-oktabr.** Turkiy tillar uchun tokenizatsiya: nima uchun bitta soʼz oʼn boʼlakka boʼlinadi.
- **15-oktabr.** Spektral yechimlar va arzon GPU lar.
- **22-oktabr.** Fargʼona vodiysi uchun sugʼorish prognozi: sunʼiy yoʼldosh maʼlumotlaridan foydalanish.
- **29-oktabr.** Ochiq muhokama: Oʼzbekistonda ilmiy hisoblash infratuzilmasi.

Har bir maʼruza yozib olinadi va keyinroq shu yerda eʼlon qilinadi.', '<p>Kuz boshlandi, biz esa oʼqishlarni qayta ochamiz. Har chorshanba soat 18:00 da laboratoriya zalida ochiq maʼruza boʼladi. Kirish bepul, roʼyxatdan oʼtish shart emas.</p>
<h2 id="dastur">Dastur</h2>
<ul>
<li><strong>8-oktabr.</strong> Turkiy tillar uchun tokenizatsiya: nima uchun bitta soʼz oʼn boʼlakka boʼlinadi.</li>
<li><strong>15-oktabr.</strong> Spektral yechimlar va arzon GPU lar.</li>
<li><strong>22-oktabr.</strong> Fargʼona vodiysi uchun sugʼorish prognozi: sunʼiy yoʼldosh maʼlumotlaridan foydalanish.</li>
<li><strong>29-oktabr.</strong> Ochiq muhokama: Oʼzbekistonda ilmiy hisoblash infratuzilmasi.</li>
</ul>
<p>Har bir maʼruza yozib olinadi va keyinroq shu yerda eʼlon qilinadi.</p>', 1, 1793793600000);
INSERT OR REPLACE INTO post_translations (post_id, locale, title, summary, body_md, body_html, reading_minutes, updated_at) VALUES ('22222222-2222-4222-8222-222222222222', 'ru', 'Осенняя программа чтений OY Lab', 'Открытые лекции по средам в октябре и ноябре: языки, научные вычисления и системы.', 'Осень началась, и мы снова открываем чтения. Каждую среду в 18:00 в зале лаборатории проходит открытая лекция. Вход свободный, регистрация не нужна.

## Программа

- **8 октября.** Токенизация для тюркских языков: почему одно слово делится на десять кусков.
- **15 октября.** Спектральные решатели на недорогих GPU.
- **22 октября.** Прогноз орошения для Ферганской долины по спутниковым данным.
- **29 октября.** Открытая дискуссия: инфраструктура научных вычислений в Узбекистане.

Каждая лекция записывается и позже публикуется здесь.', '<p>Осень началась, и мы снова открываем чтения. Каждую среду в 18:00 в зале лаборатории проходит открытая лекция. Вход свободный, регистрация не нужна.</p>
<h2 id="программа">Программа</h2>
<ul>
<li><strong>8 октября.</strong> Токенизация для тюркских языков: почему одно слово делится на десять кусков.</li>
<li><strong>15 октября.</strong> Спектральные решатели на недорогих GPU.</li>
<li><strong>22 октября.</strong> Прогноз орошения для Ферганской долины по спутниковым данным.</li>
<li><strong>29 октября.</strong> Открытая дискуссия: инфраструктура научных вычислений в Узбекистане.</li>
</ul>
<p>Каждая лекция записывается и позже публикуется здесь.</p>', 1, 1793793600000);
